  async function adjustPiezaStock(piezaId, delta) {
    const { data, error } = await sb.from("piezas").select("stock").eq("id", piezaId).single();
    if (error || !data) return;
    const nuevo = Number(data.stock) + delta;
    await sb.from("piezas").update({ stock: nuevo }).eq("id", piezaId);
  }

  // ---------------- render: clientes ----------------

  function renderClientes(list) {
    const tbody = document.getElementById("clientes-tbody");
    const empty = document.getElementById("clientes-empty");
    tbody.innerHTML = "";
    empty.hidden = list.length !== 0;
    if (!list.length) {
      empty.innerHTML = emptyStateHtml("user", "Todavía no hay clientes registrados.", "+ Agregar el primer cliente", "empty-cta-cliente");
      document.getElementById("empty-cta-cliente").addEventListener("click", () => openClienteModal(null));
    }

    list.forEach((c) => {
      const tr = document.createElement("tr");
      const vehiculosCliente = state.vehiculos.filter((v) => v.cliente_id === c.id);
      const extra = vehiculosCliente.length > 1 ? " (+" + (vehiculosCliente.length - 1) + ")" : "";
      const vehiculo = vehiculosCliente.length ? vehiculoLabel(vehiculosCliente[0]) + extra : "";
      const placa = vehiculosCliente.length ? (vehiculosCliente[0].placa || "—") + extra : "—";
      const ultimaFecha = ultimaFacturaFecha(c.id);
      const actions = [
        { key: "detalle", icon: "eye", label: "Ver detalle" },
        { key: "factura", icon: "file-text", label: "Crear factura" },
        { key: "editar", icon: "edit", label: "Editar" },
        { key: "eliminar", icon: "trash", label: "Eliminar", danger: true },
      ];
      tr.innerHTML =
        "<td>" + avatarHtml(c.nombre) + escapeHtml(c.nombre) + "</td>" +
        "<td>" + escapeHtml(c.telefono || "—") + "</td>" +
        "<td>" + escapeHtml(vehiculo || "—") + "</td>" +
        "<td>" + escapeHtml(placa) + "</td>" +
        "<td>" + (ultimaFecha ? escapeHtml(formatDate(ultimaFecha)) : "Nunca") + "</td>" +
        "<td>" + rowActionsHtml(c.id, actions) + "</td>";
      tbody.appendChild(tr);
    });

    wireRowActions(tbody, {
      detalle: (id) => openClienteDetalle(state.clientes.find((c) => c.id === id)),
      factura: (id) => crearFacturaParaCliente(state.clientes.find((c) => c.id === id)),
      editar: (id) => openClienteModal(state.clientes.find((c) => c.id === id)),
      eliminar: (id, btn) => deleteClienteRow(id, btn),
    });
  }

  async function crearFacturaParaCliente(cliente) {
    if (!cliente) return;
    goToView("facturas");
    await openFacturaModal(null);
    document.getElementById("factura-cliente").value = cliente.nombre;
  }

  function deleteClienteRow(id, btn) {
    const row = btn ? btn.closest("tr") : null;
    deleteRowWithUndo(row, "Cliente", async () => {
      const { error } = await sb.from("clientes").delete().eq("id", id);
      if (error) {
        if (error.code === "23503") {
          showToast("No se pudo eliminar: tiene órdenes o facturas asociadas.", true);
        } else {
          showToast("No se pudo eliminar el cliente.", true);
        }
        await refreshClientes();
        return;
      }
      await refreshClientes();
    }, () => renderClientes(filterClientes()));
  }

  function openClienteDetalle(cliente) {
    if (!cliente) return;
    const titleEl = document.getElementById("modal-cliente-detalle-title");
    titleEl.innerHTML =
      '<button type="button" class="breadcrumb-link" id="breadcrumb-clientes">Clientes</button><span class="breadcrumb-sep">›</span>' +
      escapeHtml(cliente.nombre);
    document.getElementById("breadcrumb-clientes").addEventListener("click", () => {
      closeModal("modal-cliente-detalle");
      goToView("clientes");
    });

    const facturaBtn = document.getElementById("btn-detalle-crear-factura");
    facturaBtn.onclick = () => {
      closeModal("modal-cliente-detalle");
      crearFacturaParaCliente(cliente);
    };

    const totalGastado = state.facturas
      .filter((f) => f.cliente_id === cliente.id && f.estado === "pagada")
      .reduce((sum, f) => sum + Number(f.total), 0);
    document.getElementById("cliente-detalle-info").innerHTML =
      "<div><span>ID Cliente</span>" + escapeHtml(String(cliente.numero || "—")) + "</div>" +
      "<div><span>Teléfono</span>" + escapeHtml(cliente.telefono || "—") + "</div>" +
      "<div><span>Email</span>" + escapeHtml(cliente.email || "—") + "</div>" +
      "<div><span>Total gastado</span>" + money(totalGastado) + "</div>";

    const vehiculosCliente = state.vehiculos.filter((v) => v.cliente_id === cliente.id);
    const vehiculosEl = document.getElementById("cliente-detalle-vehiculos");
    vehiculosEl.innerHTML = vehiculosCliente.length
      ? vehiculosCliente
          .map(
            (v) =>
              '<div class="detalle-list-item is-clickable" data-vehiculo-id="' +
              v.id +
              '"><span style="flex:1;">' +
              escapeHtml(vehiculoLabel(v)) +
              "</span><span>" +
              escapeHtml(v.placa || "Sin placa") +
              "</span><span>" +
              escapeHtml(v.kilometraje ? v.kilometraje + " mi" : "—") +
              "</span></div>"
          )
          .join("")
      : '<p class="detalle-empty">Este cliente todavía no tiene vehículos registrados.</p>';
    vehiculosEl.querySelectorAll("[data-vehiculo-id]").forEach((row) => {
      row.addEventListener("click", () => {
        openVehiculoModal(state.vehiculos.find((v) => v.id === row.dataset.vehiculoId), cliente.id);
      });
    });
    document.getElementById("btn-detalle-agregar-vehiculo").onclick = () => openVehiculoModal(null, cliente.id);

    const ordenesCliente = state.ordenes.filter((o) => o.cliente_id === cliente.id);
    const facturasCliente = state.facturas.filter((f) => f.cliente_id === cliente.id);

    const historial = [];
    ordenesCliente.forEach((o) => {
      const done = o.etapa === "completado" || o.etapa === "facturado";
      historial.push({
        tipo: "orden",
        id: o.id,
        fecha: o.fecha_recepcion,
        estadoClass: done ? "is-pagada" : "is-neutral",
        texto: "Orden #" + String(o.numero).padStart(4, "0") + " — " + (o.diagnostico || "Sin diagnóstico"),
        etiqueta: etapaLabel(o.etapa),
      });
    });
    facturasCliente.forEach((f) => {
      historial.push({
        tipo: "factura",
        id: f.id,
        fecha: f.fecha,
        estadoClass: f.estado === "pagada" ? "is-pagada" : f.estado === "cancelada" ? "is-neutral" : "is-pendiente",
        texto: "Factura #" + String(f.numero).padStart(4, "0") + " — " + money(f.total),
        etiqueta: estadoFacturaLabel(f.estado),
      });
    });
    historial.sort((a, b) => (a.fecha < b.fecha ? 1 : a.fecha > b.fecha ? -1 : 0));

    const historialEl = document.getElementById("cliente-detalle-historial");
    historialEl.innerHTML = historial.length
      ? historial
          .map(
            (h) =>
              '<div class="detalle-list-item is-clickable ' +
              h.estadoClass +
              '" data-historial-tipo="' +
              h.tipo +
              '" data-historial-id="' +
              h.id +
              '"><span class="historial-fecha">' +
              escapeHtml(h.fecha ? formatDate(h.fecha) : "Sin fecha") +
              "</span><span style=\"flex:1;\">" +
              escapeHtml(h.texto) +
              '</span><span class="pill pill-' +
              (h.estadoClass === "is-pagada" ? "pagada" : h.estadoClass === "is-pendiente" ? "pendiente" : "cancelada") +
              '">' +
              escapeHtml(h.etiqueta) +
              "</span></div>"
          )
          .join("")
      : '<p class="detalle-empty">Sin historial todavía — aún no se le ha hecho ninguna orden o factura.</p>';

    historialEl.querySelectorAll("[data-historial-id]").forEach((row) => {
      row.addEventListener("click", () => {
        const tipo = row.dataset.historialTipo;
        const itemId = row.dataset.historialId;
        closeModal("modal-cliente-detalle");
        if (tipo === "orden") {
          openOrdenModal(state.ordenes.find((o) => o.id === itemId));
        } else {
          openFacturaModal(state.facturas.find((f) => f.id === itemId));
        }
      });
    });

    const tareasCliente = state.tareas.filter((t) => t.cliente_id === cliente.id);
    const tareasEl = document.getElementById("cliente-detalle-tareas");
    tareasEl.innerHTML = tareasCliente.length
      ? tareasCliente
          .map(
            (t) =>
              '<div class="detalle-list-item"><span>' +
              escapeHtml(t.titulo) +
              "</span><span>" +
              (t.completada ? "Completada" : escapeHtml(t.fecha_vencimiento ? formatDate(t.fecha_vencimiento) : "Sin fecha")) +
              "</span></div>"
          )
          .join("")
      : '<p class="detalle-empty">Sin tareas registradas.</p>';

    openModal("modal-cliente-detalle");
  }

  function escapeHtml(str) {
    const div = document.createElement("div");
    div.textContent = String(str);
    return div.innerHTML;
  }

  function toCsv(filas) {
    if (!filas.length) return "";
    const columnas = Object.keys(filas[0]);
    const escapar = (v) => {
      if (v === null || v === undefined) return "";
      const s = String(v);
      return /[",\n]/.test(s) ? '"' + s.replace(/"/g, '""') + '"' : s;
    };
    const lineas = [columnas.join(",")];
    for (const fila of filas) lineas.push(columnas.map((c) => escapar(fila[c])).join(","));
    return lineas.join("\n");
  }

  function descargarCsv(nombreArchivo, filas) {
    if (!filas.length) {
      showToast("No hay datos todavía para exportar.", true);
      return;
    }
    const blob = new Blob([toCsv(filas)], { type: "text/csv;charset=utf-8;" });
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url;
    a.download = nombreArchivo;
    document.body.appendChild(a);
    a.click();
    a.remove();
    URL.revokeObjectURL(url);
  }

  function initials(name) {
    const parts = (name || "").trim().split(/\s+/).filter(Boolean);
    if (!parts.length) return "?";
    if (parts.length === 1) return parts[0].slice(0, 2).toUpperCase();
    return (parts[0][0] + parts[1][0]).toUpperCase();
  }

  function nameColor(name) {
    let hash = 0;
    const s = name || "";
    for (let i = 0; i < s.length; i++) hash = s.charCodeAt(i) + ((hash << 5) - hash);
    const slot = (Math.abs(hash) % 8) + 1;
    return "var(--series-" + slot + ")";
  }

  function avatarHtml(name, extraClass) {
    return (
      '<span class="avatar' +
      (extraClass ? " " + extraClass : "") +
      '" style="background:' +
      nameColor(name) +
      '">' +
      escapeHtml(initials(name)) +
      "</span>"
    );
  }

  const clientesSortState = { field: null, dir: 1 };
  const CLIENTES_SORT_LABELS = { nombre: "Nombre", telefono: "Teléfono", vehiculo: "Vehículo", vehiculo_placa: "Placa" };

  function clienteSortValue(c, field) {
    const vehiculosCliente = state.vehiculos.filter((v) => v.cliente_id === c.id);
    if (field === "vehiculo") return vehiculosCliente.length ? vehiculoLabel(vehiculosCliente[0]) : "";
    if (field === "vehiculo_placa") return vehiculosCliente.length ? vehiculosCliente[0].placa || "" : "";
    return c[field] || "";
  }

  function ultimaFacturaFecha(clienteId) {
    const facturasCliente = state.facturas.filter((f) => f.cliente_id === clienteId);
    if (!facturasCliente.length) return null;
    return facturasCliente.reduce((max, f) => (f.fecha > max ? f.fecha : max), facturasCliente[0].fecha);
  }

  function filterClientes() {
    const q = document.getElementById("clientes-search").value.trim().toLowerCase();
    const soloInactivos = document.getElementById("clientes-filter-inactivos").checked;
    let list = !q
      ? state.clientes
      : state.clientes.filter((c) => {
          return (
            (c.nombre || "").toLowerCase().includes(q) ||
            (c.telefono || "").toLowerCase().includes(q) ||
            state.vehiculos.some((v) => v.cliente_id === c.id && (v.placa || "").toLowerCase().includes(q))
          );
        });
    if (soloInactivos) {
      const limite = new Date();
      limite.setDate(limite.getDate() - 90);
      const limiteISO = limite.toISOString().slice(0, 10);
      list = list.filter((c) => {
        const ultima = ultimaFacturaFecha(c.id);
        return !ultima || ultima < limiteISO;
      });
    }
    return sortByField(list, clientesSortState, clienteSortValue);
  }

  function openClienteModal(cliente) {
    document.getElementById("modal-cliente-title").textContent = cliente ? "Editar cliente" : "Nuevo cliente";
    document.getElementById("cliente-id").value = cliente ? cliente.id : "";
    document.getElementById("cliente-nombre").value = cliente ? cliente.nombre || "" : "";
    document.getElementById("cliente-apellido").value = cliente ? cliente.apellido || "" : "";
    document.getElementById("cliente-telefono").value = cliente ? cliente.telefono || "" : "";
    document.getElementById("cliente-email").value = cliente ? cliente.email || "" : "";
    document.getElementById("cliente-direccion").value = cliente ? cliente.direccion || "" : "";
    document.getElementById("cliente-notas").value = cliente ? cliente.notas || "" : "";
    const vehiculoPrincipal = cliente ? state.vehiculos.find((v) => v.cliente_id === cliente.id) : null;
    document.getElementById("cliente-vehiculo-marca").value = vehiculoPrincipal ? vehiculoPrincipal.marca || "" : "";
    document.getElementById("cliente-vehiculo-modelo").value = vehiculoPrincipal ? vehiculoPrincipal.modelo || "" : "";
    document.getElementById("cliente-vehiculo-anio").value = vehiculoPrincipal ? vehiculoPrincipal.anio || "" : "";
    document.getElementById("btn-eliminar-cliente").hidden = !cliente;
    openModal("modal-cliente");
  }

  async function saveCliente(e) {
    e.preventDefault();
    const id = document.getElementById("cliente-id").value;
    const nombre = document.getElementById("cliente-nombre").value.trim();
    const apellido = document.getElementById("cliente-apellido").value.trim();
    const vehiculoMarca = document.getElementById("cliente-vehiculo-marca").value.trim();
    const vehiculoModelo = document.getElementById("cliente-vehiculo-modelo").value.trim();
    const vehiculoAnio = document.getElementById("cliente-vehiculo-anio").value.trim();

    if (!nombre || !apellido || !vehiculoMarca || !vehiculoModelo || !vehiculoAnio) {
      showToast("Nombre, apellido y los datos del vehículo (marca, modelo y año) son obligatorios.", true);
      return;
    }

    const payload = {
      nombre,
      apellido,
      telefono: document.getElementById("cliente-telefono").value.trim(),
      email: document.getElementById("cliente-email").value.trim(),
      direccion: document.getElementById("cliente-direccion").value.trim(),
      notas: document.getElementById("cliente-notas").value.trim(),
    };

    let error, clienteId;
    if (id) {
      clienteId = id;
      ({ error } = await sb.from("clientes").update(payload).eq("id", id));
    } else {
      const inserted = await sb.from("clientes").insert(payload).select().single();
      error = inserted.error;
      clienteId = inserted.data ? inserted.data.id : null;
    }

    if (error) {
      showToast("No se pudo guardar el cliente: " + error.message, true);
      return;
    }

    const vehiculoPayload = { cliente_id: clienteId, marca: vehiculoMarca, modelo: vehiculoModelo, anio: vehiculoAnio };
    const vehiculoExistente = state.vehiculos.find((v) => v.cliente_id === clienteId);
    if (vehiculoExistente) {
      await sb.from("vehiculos").update(vehiculoPayload).eq("id", vehiculoExistente.id);
    } else {
      await sb.from("vehiculos").insert(vehiculoPayload);
    }
    await refreshVehiculos();

    closeModal("modal-cliente");
    showToast("Cliente guardado.");
    await refreshClientes();
  }

  async function deleteCliente() {
    const id = document.getElementById("cliente-id").value;
    if (!id) return;
    if (!(await confirmDialog("¿Eliminar este cliente? Esta acción no se puede deshacer.", { title: "Eliminar cliente" }))) return;

    const { error } = await sb.from("clientes").delete().eq("id", id);
    if (error) {
      if (error.code === "23503") {
        showToast("No se puede eliminar: tiene facturas asociadas.", true);
      } else {
        showToast("No se pudo eliminar el cliente.", true);
      }
      return;
    }

    closeModal("modal-cliente");
    showToast("Cliente eliminado.");
    await refreshClientes();
  }

  async function refreshClientes() {
    renderSkeletonRows("clientes-tbody", 5, 4);
    state.clientes = await fetchClientes();
    renderClientes(filterClientes());
    populateClientesDatalist();
  }

  // ---------------- render: facturas ----------------

  const facturasSeleccionadas = new Set();

  function renderFacturas(list) {
    const tbody = document.getElementById("facturas-tbody");
    const empty = document.getElementById("facturas-empty");
    tbody.innerHTML = "";
    empty.hidden = list.length !== 0;
    if (!list.length) {
      empty.innerHTML = emptyStateHtml("file-text", "Todavía no hay facturas registradas.", "+ Crear la primera factura", "empty-cta-factura");
      document.getElementById("empty-cta-factura").addEventListener("click", () => openFacturaModal(null));
    }

    const idsVisibles = new Set(list.map((f) => f.id));
    for (const id of Array.from(facturasSeleccionadas)) {
      if (!idsVisibles.has(id)) facturasSeleccionadas.delete(id);
    }

    list.forEach((f) => {
      const tr = document.createElement("tr");
      const clienteNombre = f.clientes ? f.clientes.nombre : "—";
      const actions = [
        { key: "ver", icon: "eye", label: "Ver / editar" },
        { key: "pagada", icon: "check-circle", label: "Marcar pagada", show: f.estado !== "pagada" },
        { key: "imprimir", icon: "printer", label: "Imprimir" },
        { key: "eliminar", icon: "trash", label: "Eliminar", danger: true },
      ];
      tr.innerHTML =
        '<td><input type="checkbox" class="factura-select" data-id="' + f.id + '"' + (facturasSeleccionadas.has(f.id) ? " checked" : "") + " /></td>" +
        "<td>#" + String(f.numero).padStart(4, "0") + "</td>" +
        "<td>" + avatarHtml(clienteNombre, "avatar-sm") + escapeHtml(clienteNombre) + "</td>" +
        "<td>" + escapeHtml(formatDate(f.fecha)) + "</td>" +
        "<td>" + money(f.total) + "</td>" +
        '<td><span class="pill pill-' + f.estado + '">' + estadoFacturaLabel(f.estado) + "</span></td>" +
        "<td>" + rowActionsHtml(f.id, actions) + "</td>";
      tbody.appendChild(tr);
    });

    tbody.querySelectorAll(".factura-select").forEach((chk) => {
      chk.addEventListener("change", () => {
        if (chk.checked) facturasSeleccionadas.add(chk.dataset.id);
        else facturasSeleccionadas.delete(chk.dataset.id);
        updateFacturasBulkBar();
      });
    });

    wireRowActions(tbody, {
      ver: (id) => openFacturaModal(state.facturas.find((f) => f.id === id)),
      pagada: (id) => marcarFacturaPagada(id),
      imprimir: (id) => printFactura(id),
      eliminar: (id, btn) => deleteFacturaRow(id, btn),
    });

    updateFacturasBulkBar();
  }

  function updateFacturasBulkBar() {
    const bar = document.getElementById("facturas-bulk-bar");
    const count = facturasSeleccionadas.size;
    bar.hidden = count === 0;
    document.getElementById("facturas-bulk-count").textContent = count + (count === 1 ? " seleccionada" : " seleccionadas");

    const visibles = document.querySelectorAll(".factura-select");
    const selectAll = document.getElementById("facturas-select-all");
    const totalVisibles = visibles.length;
    const seleccionadosVisibles = Array.from(visibles).filter((c) => c.checked).length;
    selectAll.checked = totalVisibles > 0 && seleccionadosVisibles === totalVisibles;
    selectAll.indeterminate = seleccionadosVisibles > 0 && seleccionadosVisibles < totalVisibles;
  }

  function enviarFacturaEmail(id) {
    fetch(CONFIG.SUPABASE_URL + "/functions/v1/enviar-factura-email", {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        apikey: CONFIG.SUPABASE_ANON_KEY,
        Authorization: "Bearer " + CONFIG.SUPABASE_ANON_KEY,
      },
      body: JSON.stringify({ factura_id: id }),
    }).catch(() => {
      // el email es un extra silencioso; si falla no debe bloquear el flujo de cobro
    });
  }

  async function bulkMarcarPagadas() {
    if (!facturasSeleccionadas.size) return;
    const ids = Array.from(facturasSeleccionadas);
    const { error } = await sb.from("facturas").update({ estado: "pagada" }).in("id", ids);
    if (error) {
      showToast("No se pudieron marcar las facturas.", true);
      return;
    }
    ids.forEach(enviarFacturaEmail);
    showToast(ids.length + " factura(s) marcadas como pagadas.");
    facturasSeleccionadas.clear();
    await refreshFacturas();
  }

  async function bulkEliminarFacturas() {
    if (!facturasSeleccionadas.size) return;
    if (!(await confirmDialog("¿Eliminar " + facturasSeleccionadas.size + " factura(s)? Esta acción no se puede deshacer.", { title: "Eliminar facturas" }))) return;
    const ids = Array.from(facturasSeleccionadas);
    const { error } = await sb.from("facturas").delete().in("id", ids);
    if (error) {
      showToast("No se pudieron eliminar las facturas.", true);
      return;
    }
    showToast(ids.length + " factura(s) eliminadas.");
    facturasSeleccionadas.clear();
    await refreshFacturas();
  }

  async function marcarFacturaPagada(id) {
    const { error } = await sb.from("facturas").update({ estado: "pagada" }).eq("id", id);
    if (error) {
      showToast("No se pudo marcar la factura como pagada.", true);
      return;
    }
    enviarFacturaEmail(id);
    showToast("Factura marcada como pagada.");
    await refreshFacturas();
  }

  function deleteFacturaRow(id, btn) {
    const row = btn ? btn.closest("tr") : null;
    deleteRowWithUndo(row, "Factura", async () => {
      const { error } = await sb.from("facturas").delete().eq("id", id);
      if (error) {
        showToast("No se pudo eliminar la factura.", true);
        await refreshFacturas();
        return;
      }
      await refreshFacturas();
    }, () => renderFacturas(filterFacturas()));
  }

  function openPrintWindow(html) {
    let iframe = document.getElementById("print-frame");
    if (!iframe) {
      iframe = document.createElement("iframe");
      iframe.id = "print-frame";
      iframe.style.position = "fixed";
      iframe.style.right = "0";
      iframe.style.bottom = "0";
      iframe.style.width = "0";
      iframe.style.height = "0";
      iframe.style.border = "0";
      document.body.appendChild(iframe);
    }
    const doc = iframe.contentDocument || iframe.contentWindow.document;
    doc.open();
    doc.write(html);
    doc.close();
    setTimeout(() => {
      iframe.contentWindow.focus();
      iframe.contentWindow.print();
    }, 150);
  }

