  // ---------------- finanzas (ingresos, gastos, ganancias) ----------------

  const MESES = ["Enero", "Febrero", "Marzo", "Abril", "Mayo", "Junio", "Julio", "Agosto", "Septiembre", "Octubre", "Noviembre", "Diciembre"];

  async function fetchGastos() {
    return fetchConCache(
      "gastos",
      () => sb.from("gastos").select("*").order("fecha", { ascending: false }),
      [],
      "No se pudieron cargar los gastos."
    );
  }

  async function refreshGastos() {
    state.gastos = await fetchGastos();
    renderFinanzas();
  }

  function populateFinanzasAnioSelect() {
    const anioActual = new Date(todayISO()).getFullYear();
    const anios = new Set([anioActual]);
    state.facturas.forEach((f) => f.fecha && anios.add(Number(f.fecha.slice(0, 4))));
    state.gastos.forEach((g) => g.fecha && anios.add(Number(g.fecha.slice(0, 4))));

    const lista = Array.from(anios).sort((a, b) => b - a);
    if (finanzasAnio === null) finanzasAnio = anioActual;

    const select = document.getElementById("finanzas-anio");
    select.innerHTML = lista.map((a) => '<option value="' + a + '"' + (a === finanzasAnio ? " selected" : "") + ">" + a + "</option>").join("");
  }

  function renderFinanzas() {
    populateFinanzasAnioSelect();

    const anio = finanzasAnio;
    const ingresosPorMes = new Array(12).fill(0);
    const gastosPorMes = new Array(12).fill(0);

    state.facturas
      .filter((f) => f.estado === "pagada" && f.fecha && Number(f.fecha.slice(0, 4)) === anio)
      .forEach((f) => {
        const mes = Number(f.fecha.slice(5, 7)) - 1;
        ingresosPorMes[mes] += Number(f.total);
      });

    state.gastos
      .filter((g) => g.fecha && Number(g.fecha.slice(0, 4)) === anio)
      .forEach((g) => {
        const mes = Number(g.fecha.slice(5, 7)) - 1;
        gastosPorMes[mes] += Number(g.monto);
      });

    let totalIngresos = 0;
    let totalGastos = 0;

    const filas = MESES.map((nombreMes, i) => {
      const ingreso = ingresosPorMes[i];
      const gasto = gastosPorMes[i];
      const ganancia = ingreso - gasto;
      totalIngresos += ingreso;
      totalGastos += gasto;
      return (
        "<tr><td>" +
        nombreMes +
        "</td><td>" +
        money(ingreso) +
        "</td><td>" +
        money(gasto) +
        '</td><td style="color:' +
        (ganancia >= 0 ? "var(--success)" : "var(--danger)") +
        ';font-weight:600;">' +
        money(ganancia) +
        "</td></tr>"
      );
    }).join("");

    const totalGanancia = totalIngresos - totalGastos;
    const filaTotal =
      '<tr style="font-weight:700;background:var(--surface-alt);"><td>Total ' +
      anio +
      "</td><td>" +
      money(totalIngresos) +
      "</td><td>" +
      money(totalGastos) +
      '</td><td style="color:' +
      (totalGanancia >= 0 ? "var(--success)" : "var(--danger)") +
      '">' +
      money(totalGanancia) +
      "</td></tr>";

    document.getElementById("finanzas-meses-tbody").innerHTML = filas + filaTotal;

    const tbody = document.getElementById("gastos-tbody");
    const empty = document.getElementById("gastos-empty");
    tbody.innerHTML = "";
    empty.hidden = state.gastos.length !== 0;

    state.gastos.forEach((g) => {
      const tr = document.createElement("tr");
      const actions = [
        { key: "editar", icon: "edit", label: "Editar" },
        { key: "eliminar", icon: "trash", label: "Eliminar", danger: true },
      ];
      tr.innerHTML =
        "<td>" + escapeHtml(formatDate(g.fecha)) + "</td>" +
        "<td>" + escapeHtml(g.categoria || "—") + "</td>" +
        "<td>" + escapeHtml(g.descripcion || "—") + "</td>" +
        "<td>" + money(g.monto) + "</td>" +
        "<td>" + rowActionsHtml(g.id, actions) + "</td>";
      tbody.appendChild(tr);
    });

    wireRowActions(tbody, {
      editar: (id) => openGastoModal(state.gastos.find((g) => g.id === id)),
      eliminar: (id) => deleteGastoRow(id),
    });
  }

  function openGastoModal(gasto) {
    document.getElementById("modal-gasto-title").textContent = gasto ? "Editar gasto" : "Nuevo gasto";
    document.getElementById("gasto-id").value = gasto ? gasto.id : "";
    document.getElementById("gasto-fecha").value = gasto ? gasto.fecha : todayISO();
    document.getElementById("gasto-categoria").value = gasto ? gasto.categoria || "Otro" : "Renta";
    document.getElementById("gasto-descripcion").value = gasto ? gasto.descripcion || "" : "";
    document.getElementById("gasto-monto").value = gasto ? gasto.monto : 0;
    document.getElementById("btn-eliminar-gasto").hidden = !gasto;
    openModal("modal-gasto");
  }

  async function saveGasto(e) {
    e.preventDefault();
    const id = document.getElementById("gasto-id").value;
    const payload = {
      fecha: document.getElementById("gasto-fecha").value,
      categoria: document.getElementById("gasto-categoria").value,
      descripcion: document.getElementById("gasto-descripcion").value.trim(),
      monto: parseFloat(document.getElementById("gasto-monto").value) || 0,
    };

    let error;
    if (id) {
      ({ error } = await sb.from("gastos").update(payload).eq("id", id));
    } else {
      ({ error } = await sb.from("gastos").insert(payload));
    }

    if (error) {
      showToast("No se pudo guardar el gasto.", true);
      return;
    }

    closeModal("modal-gasto");
    showToast("Gasto guardado.");
    await refreshGastos();
  }

  async function deleteGastoRow(id) {
    if (!id) return;
    if (!(await confirmDialog("¿Eliminar este gasto?", { title: "Eliminar gasto" }))) return;
    const { error } = await sb.from("gastos").delete().eq("id", id);
    if (error) {
      showToast("No se pudo eliminar el gasto.", true);
      return;
    }
    closeModal("modal-gasto");
    showToast("Gasto eliminado.");
    await refreshGastos();
  }

