  function renderDashboard() {
    const hoy = todayISO();
    const mesActual = hoy.slice(0, 7);

    const ingresosMes = state.facturas
      .filter((f) => f.estado === "pagada" && (f.fecha || "").slice(0, 7) === mesActual)
      .reduce((sum, f) => sum + Number(f.total), 0);

    const pendientes = state.facturas.filter((f) => f.estado === "pendiente");
    const pendientesMonto = pendientes.reduce((sum, f) => sum + Number(f.total), 0);

    const ordenesActivas = state.ordenes.filter((o) => o.etapa !== "facturado" && o.etapa !== "cancelado");

    const tareasVencidas = state.tareas.filter((t) => !t.completada && t.fecha_vencimiento && t.fecha_vencimiento < hoy);

    const stockBajo = state.piezas.filter((p) => Number(p.stock) <= Number(p.stock_minimo));

    document.getElementById("kpi-ingresos").textContent = money(ingresosMes);
    document.getElementById("kpi-facturas-pendientes").textContent = String(pendientes.length);
    document.getElementById("kpi-facturas-pendientes-monto").textContent = money(pendientesMonto);
    document.getElementById("kpi-ordenes-activas").textContent = String(ordenesActivas.length);
    document.getElementById("kpi-tareas-vencidas").textContent = String(tareasVencidas.length);
    document.getElementById("kpi-stock-bajo").textContent = String(stockBajo.length);

    const counts = document.getElementById("dashboard-etapa-counts");
    counts.innerHTML = ETAPAS.map((etapa) => {
      const n = state.ordenes.filter((o) => o.etapa === etapa.key).length;
      return '<span class="etapa-count-item">' + etapa.label + ": <strong>" + n + "</strong></span>";
    }).join("");

    const pagadas = state.facturas.filter((f) => f.estado === "pagada").sort((a, b) => (a.fecha < b.fecha ? 1 : -1));
    const pendientesOrdenadas = pendientes.slice().sort((a, b) => (a.fecha < b.fecha ? 1 : -1));

    renderPagoPanel("pago-panel-pendientes", pendientesOrdenadas);
    renderPagoPanel("pago-panel-pagadas", pagadas);
    document.getElementById("pago-panel-pendientes-count").textContent = String(pendientesOrdenadas.length);
    document.getElementById("pago-panel-pagadas-count").textContent = String(pagadas.length);

    renderDashboardChart();
    updateQuickAccessBadges();
  }

  function renderDashboardChart() {
    const canvas = document.getElementById("dashboard-chart");
    if (!canvas || !canvas.getContext) return;
    const ctx = canvas.getContext("2d");

    const cssWidth = canvas.clientWidth || 600;
    canvas.width = cssWidth;
    canvas.height = 180;
    const W = canvas.width;
    const H = canvas.height;
    ctx.clearRect(0, 0, W, H);

    const hoy = new Date(todayISO());
    const meses = [];
    for (let i = 5; i >= 0; i--) {
      const d = new Date(hoy.getFullYear(), hoy.getMonth() - i, 1);
      const key = d.getFullYear() + "-" + String(d.getMonth() + 1).padStart(2, "0");
      meses.push({ key, label: MESES[d.getMonth()].slice(0, 3) });
    }

    const totales = meses.map((m) => state.facturas.filter((f) => f.estado === "pagada" && (f.fecha || "").slice(0, 7) === m.key).reduce((sum, f) => sum + Number(f.total), 0));
    const max = Math.max(1, ...totales);

    const paddingBottom = 28;
    const paddingTop = 22;
    const plotH = H - paddingBottom - paddingTop;
    const n = meses.length;
    const gap = 14;
    const barW = (W - gap * (n + 1)) / n;

    const styles = getComputedStyle(document.documentElement);
    const accent = styles.getPropertyValue("--accent").trim() || "#d5601a";
    const textDim = styles.getPropertyValue("--text-dim").trim() || "#68707e";
    const textFaint = styles.getPropertyValue("--text-faint").trim() || "#98a1b0";

    ctx.font = "11px -apple-system, sans-serif";
    ctx.textAlign = "center";

    meses.forEach((m, i) => {
      const x = gap + i * (barW + gap);
      const h = (totales[i] / max) * plotH;
      const y = paddingTop + (plotH - h);

      ctx.fillStyle = accent;
      if (ctx.roundRect) {
        ctx.beginPath();
        ctx.roundRect(x, y, barW, Math.max(h, 2), [4, 4, 0, 0]);
        ctx.fill();
      } else {
        ctx.fillRect(x, y, barW, Math.max(h, 2));
      }

      ctx.fillStyle = textDim;
      ctx.fillText(m.label, x + barW / 2, H - paddingBottom + 16);

      if (totales[i] > 0) {
        ctx.fillStyle = textFaint;
        ctx.fillText(money(totales[i]).replace(".00", ""), x + barW / 2, y - 6);
      }
    });
  }

  function renderPagoPanel(containerId, facturasList) {
    const el = document.getElementById(containerId);
    if (!facturasList.length) {
      el.innerHTML = '<p class="detalle-empty">Nada por aquí.</p>';
      return;
    }
    el.innerHTML = facturasList
      .map(
        (f) =>
          '<div class="pago-item" data-pago-factura="' +
          f.id +
          '"><span class="pago-item-cliente">' +
          avatarHtml(f.clientes ? f.clientes.nombre : "—", "avatar-sm") +
          escapeHtml(f.clientes ? f.clientes.nombre : "—") +
          "</span><span class=\"pago-item-meta\">" +
          money(f.total) +
          " · " +
          escapeHtml(formatDate(f.fecha)) +
          "</span></div>"
      )
      .join("");
    el.querySelectorAll("[data-pago-factura]").forEach((row) => {
      row.addEventListener("click", () => {
        const factura = state.facturas.find((f) => f.id === row.dataset.pagoFactura);
        if (factura) openFacturaModal(factura);
      });
    });
  }

